GUIDES = [
 {"slug":"change-order-template-for-freelancers","tag":"Scope & contracts","lang":"en",
  "title":"Change Order Template for Freelancers (Free) | SeeGlance",
  "h1":"Change order template for freelancers: stop scope creep without fighting your client",
  "desc":"A free change order template, a 4-step process and the exact wording to turn 'quick extra request' into paid work — plus how an AI scope check helps.",
  "lede":"Scope creep rarely arrives as a big ask. It arrives as “one small thing”. A change order turns that small thing into a written, priced, approved addition — without an awkward conversation. Here is a template, the process, and the wording.",
  "alt":("vi","phu-luc-thay-doi-pham-vi-change-order-cho-freelancer"),
  "related":["milestone-invoicing-deposit-template","freelance-time-tracking-to-invoice","late-payment-reminder-email-templates"],
  "cta_text":"Send a change order as a link your client approves in one click, with the amount, extra days and a record of who approved it. Pro includes the AI scope guard.",
  "faqs":[("What is a change order in freelancing?","A change order is a short written agreement that adds, removes or changes work after the original contract or proposal was accepted. It states what changes, the price, and any change to the deadline, and the client approves it before you start."),
          ("When should I charge for a change instead of absorbing it?","Charge when the request is not covered by the written scope, needs meaningful extra time, or changes the deliverable (new pages, extra revision rounds, new formats). Absorb tiny tweaks on purpose and say so, so the client knows it was a favour, not the new normal."),
          ("Does a client have to sign a change order?","Legally that depends on your contract and local law, so ask a lawyer if the amounts are large. In practice a clear written approval (a signature, or an explicit approve action that records the name and time) is what protects you."),
          ("Can AI decide if a request is out of scope?","It can compare the request with the written scope and point to the lines that support its answer, but it is an assistant, not a lawyer. If the scope text is vague, the honest answer is “unclear” and you decide.")]},
 {"slug":"milestone-invoicing-deposit-template","tag":"Invoicing","lang":"en",
  "title":"Milestone Invoicing: Deposit Splits & Template | SeeGlance",
  "h1":"Milestone invoicing for freelancers: deposit splits that protect your cash flow",
  "desc":"How to split a project into deposit, milestone and final invoices: 50/50, 30/40/30 and 30/70 examples, what to write on each invoice, and when to start work.",
  "lede":"If you invoice only at the end, you are lending your client money for free. A deposit and a few milestones fix that. This guide shows three splits that work, when each fits, and how to word it so clients agree.",
  "related":["change-order-template-for-freelancers","late-payment-reminder-email-templates","freelance-retainer-agreement-and-recurring-invoices"],
  "cta_text":"Set a payment schedule from presets (50/50, 30/40/30, 30/70), then turn each milestone into an invoice when it is due.",
  "faqs":[("What deposit should a freelancer ask for?","Common ranges are 30 to 50 percent for projects of a few weeks. Smaller or first-time clients often get a higher deposit. Fixed-price work with big up-front costs justifies the high end."),
          ("Should work start before the deposit is paid?","No. State in the proposal or contract that the start date is confirmed once the deposit is received. Starting free work is the most common way freelancers end up unpaid."),
          ("What if the client wants to pay everything at the end?","Offer a smaller project phase to pay in full first, a smaller deposit with a milestone, or hand over low-resolution or watermarked previews until the final payment clears."),
          ("How do change orders fit into milestones?","Approved change orders are billed as their own line or invoice, so the original schedule stays clean.")]},
 {"slug":"freelance-retainer-agreement-and-recurring-invoices","tag":"Retainers","lang":"en",
  "title":"Freelance Retainer: Pricing & Auto-Invoicing | SeeGlance",
  "h1":"How to set up a freelance retainer (and invoice it without chasing)",
  "desc":"What a retainer is, how to price it, what to put in the agreement, and how to automate weekly, monthly or quarterly invoices with included hours.",
  "lede":"A retainer swaps unpredictable project income for a recurring fee. The hard parts are pricing it, defining what is included, and sending the invoice on time every period. Here is how to do all three.",
  "related":["milestone-invoicing-deposit-template","late-payment-reminder-email-templates","freelance-time-tracking-to-invoice"],
  "cta_text":"Create a retainer once: amount, interval, first invoice date and included hours. SeeGlance creates and optionally sends each invoice for you.",
  "faqs":[("How much should a freelance retainer cost?","Start from the hours you commit to, multiplied by your normal rate, then apply a modest discount (many freelancers use 5 to 15 percent) in exchange for guaranteed income and priority. Never discount below your effective minimum."),
          ("What happens to unused hours?","Decide it up front. Most retainers say unused hours expire at the end of the period, because you reserved the capacity. Rolling over for one period is a common compromise."),
          ("Weekly, monthly or quarterly billing?","Monthly suits most clients. Weekly or every two weeks suits cash-tight clients or high-volume work. Quarterly suits stable clients who prefer fewer invoices; consider a deposit-style first payment."),
          ("How do I end a retainer?","Write a notice period (for example 30 days) and an end date option. Recurring invoices should stop at the end date or when you pause them.")]},
 {"slug":"late-payment-reminder-email-templates","tag":"Getting paid","lang":"en",
  "title":"Late Payment Reminder Email Templates | SeeGlance",
  "h1":"Late payment reminder emails: 5 templates and when to send each",
  "desc":"Copy-paste payment reminder emails from friendly heads-up to final notice, with a simple schedule: 3 days before, on the due date, then 3, 7 and 14 days late.",
  "lede":"Most late invoices are forgotten, not refused. A calm, predictable sequence of reminders recovers most of them without damaging the relationship. Here is a five-step schedule and the wording for each step.",
  "related":["milestone-invoicing-deposit-template","paypal-vs-wise-vs-payoneer-fees-for-freelancers","freelance-retainer-agreement-and-recurring-invoices"],
  "cta_text":"Turn on auto-reminders per invoice and SeeGlance sends this exact five-step sequence, never the same stage twice, and leaves very late invoices to you.",
  "faqs":[("How soon after the due date should I send a reminder?","Send a friendly note on the due date and a second after about 3 days. Waiting longer teaches clients that your due dates are flexible."),
          ("Should I charge late fees?","Only if your contract or invoice terms say so before the work. Check what is legal in your country, then state the rate and grace period clearly."),
          ("When should I stop sending automated reminders?","After roughly six weeks past due, switch to a personal call or message and consider pausing further work. Automated tone is wrong for a seriously overdue account."),
          ("What if the client says they never got the invoice?","Resend it with a payment link, confirm the email address, and keep the timestamped record of the original send.")]},
 {"slug":"w-8ben-form-guide-for-freelancers-outside-the-us","tag":"Tax forms","lang":"en",
  "title":"W-8BEN Guide for Freelancers Outside the US | SeeGlance",
  "h1":"W-8BEN for freelancers outside the US: line-by-line guide",
  "desc":"What the W-8BEN is, when US clients ask for it, how to fill each line, how long it stays valid, and what to do when your country has no treaty.",
  "lede":"A US client sends you a W-8BEN and you do not know what to write. This guide explains what the form is for, goes through every line, and shows how to track when it expires.",
  "alt":("vi","w-8ben-cho-freelancer-viet-nam-huong-dan-dien-tung-dong"),
  "related":["paypal-vs-wise-vs-payoneer-fees-for-freelancers","late-payment-reminder-email-templates","change-order-template-for-freelancers"],
  "cta_text":"Use the built-in W-8BEN helper to see what to write on each line, then track the signing date and expiry per client.",
  "faqs":[("Do I need a W-8BEN as a freelancer outside the US?","Many US companies ask for one before paying a foreign individual, so they can document that you are not a US person. Whether a given payment is actually subject to US tax depends on where the work is performed and on your situation, so ask the client and a tax adviser."),
          ("What happens if I do not submit a W-8BEN?","The payer may be required to withhold tax at the default statutory rate, often described as 30 percent, on US-source payments. Without a valid signed form they also cannot apply treaty benefits you may be entitled to."),
          ("How long is a W-8BEN valid?","Generally until the end of the third calendar year after the year you sign it (sign in 2026 and it normally runs to 31 December 2029), unless your circumstances change earlier."),
          ("My country has no tax treaty with the US. What do I put in Part II?","If you are not claiming treaty benefits, leave the treaty lines blank and complete the rest. Check current treaty status before assuming. For example, per a source updated in May 2026, no US–Vietnam income tax treaty is currently in force. Always check the current status."),
          ("Do I send the W-8BEN to the IRS?","No. You give it to the person or company paying you. They keep it on file.")]},
 {"slug":"paypal-vs-wise-vs-payoneer-fees-for-freelancers","tag":"Payments","lang":"en",
  "title":"PayPal vs Wise vs Payoneer: What You Keep | SeeGlance",
  "h1":"PayPal vs Wise vs Payoneer: how to work out what you actually keep",
  "desc":"A repeatable way to compare payout fees for freelancers: receiving fee, currency conversion spread, withdrawal fee. Includes a worked example and a checklist.",
  "lede":"Headline fees mislead. The cost that hurts is the sum of three: what is taken when money arrives, the spread when currency is converted, and the fee to withdraw to your local bank. This guide gives you a method to compare any payout route for your own country.",
  "related":["w-8ben-form-guide-for-freelancers-outside-the-us","milestone-invoicing-deposit-template","late-payment-reminder-email-templates"],
  "cta_text":"The fee estimator lets you edit every number and shows your net on each payout method — and the invoice editor shows the estimate before you send.",
  "faqs":[("Which is cheapest for freelancers: PayPal, Wise or Payoneer?","It depends on your country, the invoice currency, the amount and your account tier. Wise is often cheapest when the client can pay by local bank transfer, and PayPal is often the most expensive after conversion. Run the three-fee calculation with current numbers instead of trusting a headline percentage."),
          ("What is the currency conversion spread?","It is the gap between the rate you receive and the mid-market rate. It is frequently larger than the stated fee, especially on card-based providers."),
          ("Should I invoice in USD or my local currency?","Invoice in the currency your client budgets in. Avoid being forced to convert twice; receive in the invoice currency and convert once, at a provider with a transparent rate."),
          ("Does SeeGlance hold my money?","No. Invoices carry a payment link to the payout method you choose (Payoneer, Wise, Skrill or a crypto wallet). The money goes to you directly.")]},
 {"slug":"freelance-time-tracking-to-invoice","tag":"Time tracking","lang":"en",
  "title":"Freelance Time Tracking to Invoice Guide | SeeGlance",
  "h1":"Freelance time tracking to invoice: turn hours into a clean bill",
  "desc":"How to track billable hours, describe them so clients accept the invoice, avoid double-billing, and convert tracked time into an invoice in a few clicks.",
  "lede":"Hourly work fails in two places: hours you forget to log, and invoices clients dispute because the line items are vague. A simple routine fixes both.",
  "related":["freelance-retainer-agreement-and-recurring-invoices","change-order-template-for-freelancers","paying-subcontractors-and-measuring-project-profit"],
  "cta_text":"Log time against a project, mark what is billable, then create the invoice from the unbilled entries so nothing is billed twice.",
  "faqs":[("How detailed should time entry descriptions be?","One line that a non-expert can understand: what was done and why. “Homepage layout, 3 revisions” beats “design”."),
          ("Should I round time up?","Round consistently and say how in your terms (for example to the nearest 15 minutes). Do not round up silently; it destroys trust."),
          ("Can I mix hourly and fixed price?","Yes. Keep fixed-price milestones and hourly extras separate, and use change orders for out-of-scope hours."),
          ("How do I avoid double-billing?","Mark entries as billed when they go onto an invoice. SeeGlance links each entry to its invoice so it cannot appear twice.")]},
 {"slug":"paying-subcontractors-and-measuring-project-profit","tag":"Agencies & Teams","lang":"en",
  "title":"Paying Subcontractors & Project Profit | SeeGlance",
  "h1":"Paying subcontractors and measuring real project profit",
  "desc":"How freelancers who bring in contractors can track cost per project, bill markup fairly, and see margin by project, client and team member.",
  "lede":"The first time you hire help, revenue goes up and profit becomes harder to see. Contractor payments, expenses and your own time all need to land on the right project. Here is a simple way to keep the numbers honest.",
  "related":["team-project-budgets-timesheet-lock-and-workload","freelance-time-tracking-to-invoice","change-order-template-for-freelancers"],
  "cta_text":"Add contractors and expenses to a project and see its profit and margin. The Team plan adds the cross-project profit report.",
  "faqs":[("How much markup should I add to subcontractor work?","There is no standard number. Work out your target margin first, then price so contractor cost plus your management time still leaves it. Many agencies aim for a clear margin on every project and test it quarterly."),
          ("Do I need a contract with each subcontractor?","Yes: scope, rate, deadline, IP assignment and confidentiality at minimum. Laws about classification differ by country, so get local advice."),
          ("What counts as project cost?","Contractor payments, software or stock bought for the job, and the value of your own and your team’s time. Leaving time out makes every project look more profitable than it was."),
          ("How often should I review margin?","After each project closes, and monthly across projects, to spot the client types that quietly cost you money.")]},
 {"slug":"team-project-budgets-timesheet-lock-and-workload","tag":"Agencies & Teams","lang":"en",
  "title":"Agency Project Budgets, Timesheets & Workload | SeeGlance",
  "h1":"Run a small studio without surprises: budgets, timesheets and workload",
  "desc":"How to set project hour and cost budgets with alerts at 80% and 100%, lock timesheets after invoicing, and see whether your team is over- or under-booked.",
  "lede":"A team of three makes new problems: projects that quietly burn through their hours, edited timesheets after the invoice went out, and one person always overloaded. Four habits handle most of it.",
  "related":["paying-subcontractors-and-measuring-project-profit","freelance-time-tracking-to-invoice","change-order-template-for-freelancers"],
  "cta_text":"Team plan: $29/month with 3 seats included. Budgets with alerts, timesheet lock, workload report, assigned tasks and a Monday digest.",
  "faqs":[("What is a good project budget alert threshold?","80 percent gives you time to act: renegotiate, send a change order or re-plan. 100 percent means the budget is gone. Alerting only at 100 percent is too late."),
          ("Why lock timesheets?","Once hours are invoiced or paid, changes cause disputes and wrong profit numbers. Locking up to a date stops members from editing history while admins can still correct genuine mistakes."),
          ("How is utilisation calculated?","Logged hours divided by the person’s weekly capacity. A 40-hour week with 30 logged hours is 75 percent. Billable utilisation looks only at billable hours."),
          ("How many people does the Team plan include?","Three seats are included; extra seats cost $7/month each.")]},
 {"slug":"phu-luc-thay-doi-pham-vi-change-order-cho-freelancer","tag":"Hợp đồng & phạm vi","lang":"vi",
  "title":"Mẫu Change Order cho Freelancer | SeeGlance",
  "h1":"Mẫu phụ lục thay đổi phạm vi (change order) cho freelancer: chặn scope creep mà không mất lòng khách",
  "desc":"Mẫu change order miễn phí, quy trình 4 bước và câu chữ sẵn dùng để biến yêu cầu “thêm chút xíu” thành việc có báo giá và có xác nhận bằng văn bản.",
  "lede":"Scope creep hiếm khi đến dưới dạng một yêu cầu lớn. Nó đến dưới dạng “nhờ thêm một chút”. Change order biến “một chút” đó thành phần việc được ghi rõ, có giá và được khách duyệt trước khi bạn bắt tay làm.",
  "alt":("en","change-order-template-for-freelancers"),
  "related":["w-8ben-cho-freelancer-viet-nam-huong-dan-dien-tung-dong"],
  "cta_text":"Gửi change order dưới dạng link để khách bấm duyệt, có số tiền, số ngày thêm và ghi lại tên người duyệt. Gói Pro có thêm AI scope guard.",
  "faqs":[("Change order là gì?","Là văn bản ngắn thỏa thuận thêm, bớt hoặc thay đổi công việc sau khi hợp đồng hoặc proposal đã được chấp nhận, ghi rõ nội dung thay đổi, giá tiền và thay đổi thời hạn (nếu có)."),
          ("Khi nào nên tính phí thay vì làm miễn phí?","Khi yêu cầu nằm ngoài phạm vi đã ghi, cần thêm thời gian đáng kể hoặc làm thay đổi sản phẩm bàn giao. Nếu nhận làm miễn phí thì hãy nói rõ đó là ngoại lệ."),
          ("Khách có bắt buộc phải ký không?","Tùy hợp đồng và luật địa phương nên hãy hỏi luật sư với số tiền lớn. Trên thực tế, một xác nhận bằng văn bản rõ ràng (có tên và thời điểm duyệt) là điều bảo vệ bạn.")]},
 {"slug":"w-8ben-cho-freelancer-viet-nam-huong-dan-dien-tung-dong","tag":"Biểu mẫu thuế","lang":"vi",
  "title":"Hướng dẫn điền W-8BEN cho Freelancer VN | SeeGlance",
  "h1":"Hướng dẫn điền W-8BEN cho freelancer Việt Nam: từng dòng một",
  "desc":"W-8BEN là gì, khi nào khách Mỹ yêu cầu, cách điền từng dòng, hiệu lực bao lâu và cách xử lý phần hiệp ước thuế khi Việt Nam chưa có hiệp định.",
  "lede":"Khách Mỹ gửi bạn mẫu W-8BEN và bạn không biết điền gì. Bài này giải thích mẫu dùng để làm gì, đi qua từng dòng và cách theo dõi ngày hết hạn.",
  "alt":("en","w-8ben-form-guide-for-freelancers-outside-the-us"),
  "related":["phu-luc-thay-doi-pham-vi-change-order-cho-freelancer"],
  "cta_text":"Dùng trợ lý W-8BEN có sẵn để xem cần điền gì ở mỗi dòng, rồi theo dõi ngày ký và ngày hết hạn theo từng khách hàng.",
  "faqs":[("Freelancer Việt Nam có cần W-8BEN không?","Nhiều công ty Mỹ yêu cầu mẫu này trước khi trả tiền cho cá nhân nước ngoài. Khoản tiền có bị đánh thuế Mỹ hay không còn tùy nơi bạn thực hiện công việc và hoàn cảnh cụ thể, nên hãy hỏi khách và chuyên gia thuế."),
          ("Không nộp W-8BEN thì sao?","Bên trả tiền có thể phải khấu trừ thuế ở mức mặc định, thường được nhắc đến là 30%, với khoản thu nhập nguồn Mỹ, và không áp dụng được ưu đãi hiệp định."),
          ("W-8BEN có hiệu lực bao lâu?","Thông thường đến hết năm dương lịch thứ ba sau năm bạn ký (ký năm 2026 thì thường đến 31/12/2029), trừ khi hoàn cảnh thay đổi sớm hơn."),
          ("Việt Nam có hiệp định thuế với Mỹ không?","Theo một nguồn cập nhật tháng 5/2026, hiện chưa có hiệp định thuế thu nhập Mỹ–Việt nào đang có hiệu lực. Vì vậy thường để trống phần hiệp ước (Part II) nếu bạn không yêu cầu ưu đãi, nhưng hãy kiểm tra lại tình trạng hiện hành.")]},
]
